(R/'README.zh-TW.md').write_text('# Koma Studio 0.5.0-alpha / Pro Desk\n\n'+features[0][1]+' / '+features[1][1]+' / '+features[2][1]+' / '+features[3][1]+' / '+features[4][1]+' / '+features[5][1]+' / '+features[6][1]+' / '+features[7][1]+' / '+features[8][1]+' / '+features[9][1]+'\n\n'+u('Node.js 20 \u6216\u4ee5\u4e0a\uff0c\u57f7\u884c `node server.cjs`\uff1b\u4e0d\u9700\u5b89\u88dd npm \u5957\u4ef6\u3002\n\n\u958b\u555f `Guide.zh-TW.html` \u95b1\u8b80\u5b8c\u6574\u64cd\u4f5c\u65b9\u5f0f\u8207\u80fd\u529b\u908a\u754c\u3002\n\n\u76f4\u63a5\u9ad4\u9a57\uff1a`Koma-Ninja-Pro.html`\uff1b\u6b63\u5f0f\u4f7f\u7528\uff1a`Koma-Production-Standalone.html` \u6216\u672c\u6a5f\u4f3a\u670d\u5668\u3002\n\n\u4fee\u6539\u5f8c\u8acb\u53e6\u5b58\u5c08\u6848\u8207\u5b8c\u6574\u5099\u4efd\u3002\u672c\u7248\u4e0d\u9700\u8a02\u95b1\u3001\u767b\u5165\u6216\u4ed8\u8cbb API\uff1b\u4e0d\u5305\u542b\u751f\u6210\u6a21\u578b\u3002\n\n\u4ee3\u7406\u4f7f\u7528\u898b `AGENTS.md` \u53ca `docs/PRO-COMMANDS.md`\u3002\u6e2c\u8a66\u8b49\u64da\u898b `evidence/v050`\u3002\u5c1a\u672a\u9a57\u8b49\u4f60\u7684 Codex\u3001\u5be6\u9ad4\u58d3\u611f\u7b46\u6216\u9577\u7247\u9ad8\u8ca0\u8f09\u3002\n'),encoding='utf8')
status='# Release scope: 0.5.0-alpha\n\nTen Pro authoring families are integrated with the existing P0-P2 core. No commercial-suite parity claim.\n\n'
